    private static IEnumerable<string> Expand(string specification){
        foreach(var item in specification.Split(' ')){
            if(item[0]=='2'){yield return item[1..];yield return item[1..];}
            else yield return item;
        }
    }
    internal static List<CardModel>? Build(LeagueArchetypes.Plan plan,LeagueCards.Entry[] pool,Random rng){
        if(!Kits.TryGetValue(plan.Title,out var kit))return null;
        var catalog=pool.ToDictionary(c=>c.Id);var counts=new Dictionary<string,int>();
        int neutral=0;
        void Add(LeagueCards.Entry c){counts[c.Id]=counts.GetValueOrDefault(c.Id)+1;if(c.Group=="COLORLESS")neutral++;}
        foreach(var c in pool)for(int n=LeagueCards.Fixed(c);n>0;n--)Add(c);
        var bands=new[]{kit.Commons,kit.Blues,kit.Golds,kit.Ancient};
        for(int grade=0;grade<bands.Length;grade++)foreach(var id in Expand(bands[grade])){
            if(!catalog.TryGetValue(id,out var c)||c.Tier!=grade)return null;
            Add(c);
        }
        if(counts.Values.Sum()!=LeagueCards.DeckSize)return null;
        var engine=LeagueArchetypes.Engines[plan.Role];
        var forgeCopies=Expand(kit.Forge).GroupBy(id=>id).ToDictionary(g=>g.Key,g=>g.Count());
        foreach(var group in Alternatives[plan.Role]){
            int Required(string id)=>Math.Max(forgeCopies.GetValueOrDefault(id),
                plan.Anchors.Contains(id)||plan.Starters.Contains(id)||plan.Finishers.Contains(id)?1:0);
            var sources=group.Where(k=>counts.GetValueOrDefault(k)>Required(k)).ToArray();
            if(sources.Length==0)continue;
            string from=sources[rng.Next(sources.Length)];var old=catalog[from];
            var options=group.Where(k=>catalog.TryGetValue(k,out var c)&&c.Tier==old.Tier&&(k==from||counts.GetValueOrDefault(k)<2)&&
                (!engine.Draw.Contains(from)||engine.Draw.Contains(k))&&(!engine.Energy.Contains(from)||engine.Energy.Contains(k))&&
                (c.Group!="COLORLESS"||old.Group=="COLORLESS"||neutral<LeagueCards.NeutralLimit)&&LeagueArchetypes.CanSupportAnother(k,counts)).ToArray();
            if(options.Length==0)continue;
            string to=options[rng.Next(options.Length)];if(to==from)continue;
            if(--counts[from]==0)counts.Remove(from);if(old.Group=="COLORLESS")neutral--;Add(catalog[to]);
        }
        return counts.OrderBy(p=>p.Key,StringComparer.Ordinal).SelectMany(p=>Enumerable.Repeat(catalog[p.Key].Model,p.Value)).ToList();
    }
    internal static IEnumerable<CardModel> ForgeOrder(CardModel[] cards,LeagueArchetypes.Plan plan){
        if(!Kits.TryGetValue(plan.Title,out var kit))return [];
        var remaining=cards.ToList();var selected=new List<CardModel>();
        foreach(var key in Expand(kit.Forge)){
            int i=remaining.FindIndex(c=>c.Id.Entry==key&&c.MaxUpgradeLevel>0);if(i<0)continue;
            selected.Add(remaining[i]);remaining.RemoveAt(i);
        }
        return selected;
    }
